-- NutriTrack relational schema (MySQL 8 compatible). Flask SQLAlchemy creates the equivalent tables for SQLite on first run.
CREATE DATABASE IF NOT EXISTS nutritrack CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nutritrack;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, age INT DEFAULT 25, gender VARCHAR(30), height_cm DECIMAL(6,2), weight_kg DECIMAL(6,2), activity_level VARCHAR(30), goal VARCHAR(20), preferences JSON, restrictions JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS foods (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, calories DECIMAL(8,2) NOT NULL, protein DECIMAL(8,2) DEFAULT 0, carbs DECIMAL(8,2) DEFAULT 0, fat DECIMAL(8,2) DEFAULT 0, fibre DECIMAL(8,2) DEFAULT 0, serving_size VARCHAR(80), category VARCHAR(50), INDEX idx_food_name(name));
CREATE TABLE IF NOT EXISTS meal_logs (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, food_id INT NULL, food_name VARCHAR(120) NOT NULL, meal_type VARCHAR(20) DEFAULT 'lunch', quantity DECIMAL(8,2) DEFAULT 1, calories DECIMAL(9,2) DEFAULT 0, protein DECIMAL(8,2) DEFAULT 0, carbs DECIMAL(8,2) DEFAULT 0, fat DECIMAL(8,2) DEFAULT 0, fibre DECIMAL(8,2) DEFAULT 0, logged_at DATETIME DEFAULT CURRENT_TIMESTAMP, notes VARCHAR(255), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(food_id) REFERENCES foods(id) ON DELETE SET NULL, INDEX idx_meal_user_date(user_id, logged_at));
CREATE TABLE IF NOT EXISTS goals (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, calories INT DEFAULT 2000, protein DECIMAL(8,2) DEFAULT 100, carbs DECIMAL(8,2) DEFAULT 250, fat DECIMAL(8,2) DEFAULT 67, water_ml INT DEFAULT 2000, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS meal_plans (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, plan_date DATE, title VARCHAR(120), meals_json JSON NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_plan_user_date(user_id, plan_date));
CREATE TABLE IF NOT EXISTS weight_logs (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, weight_kg DECIMAL(6,2) NOT NULL, logged_on DATE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_weight_user_date(user_id, logged_on));
-- Demo user is seeded by backend/app.py so its password can be safely hashed at runtime.
